    ('86e6479a-a9be-546f-b584-fe317507dfe0'::uuid, '5ba6788a-10fa-5c00-86ad-6c71b1265e86'::uuid, 'Qui n’a laissé aucun écrit de sa main ?', 'mcq', '["Socrate","Platon","Aristote","Sophocle"]'::jsonb, 0, 'On le connaît par Platon et Xénophon.', 4),
    ('ba9114d2-aaff-5b39-9a89-dad84b2255dc'::uuid, '5ba6788a-10fa-5c00-86ad-6c71b1265e86'::uuid, 'Aristophane est un auteur de comédies.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il raille les politiques et les intellectuels de son temps.', 5),
